public void setHorizontalLinesCheckbox(NSButton horizontalLinesCheckbox) {
  this.horizontalLinesCheckbox = horizontalLinesCheckbox;
  this.horizontalLinesCheckbox.setTarget(this);
  this.horizontalLinesCheckbox.setAction(new NSSelector("horizontalLinesCheckboxClicked", new Class[]{NSButton.class}));
  try {
    this.horizontalLinesCheckbox.setState(
      Preferences.instance().getProperty("browser.horizontalLines").equals("true") ? NSCell.OnState : NSCell.OffState
    );
  } catch (SecurityException e) {
    System.err.println("SecurityException: Unable to access property 'browser.horizontalLines'. " + e.getMessage());
  } catch (IllegalArgumentException e) {
    System.err.println("IllegalArgumentException: Property 'browser.horizontalLines' not found. " + e.getMessage());
  }
}
